    const TIPC = ['อีกเรื่องที่แนะนำคือ', 'ขอแนะนำเพิ่มอีกข้อคือ', 'เคล็ดเล็กๆ ที่ช่วยได้คือ'];

    // รายยาม: ธาตุนี้ในดวงคุณหมายถึงอะไร (ตามสิบเทพ)
    const MEAN = { '比肩': 'คนที่เสมอกัน เช่น เพื่อน พี่น้อง และคนในทีม', '劫财': 'คนรอบตัวที่มาแบ่งปันหรือแข่งขันกับคุณ', '食神': 'ความสุขใจ ความคิดสร้างสรรค์ และฝีมือ', '伤官': 'ความคิดที่แหลมคมและคำพูด',
        '偏财': 'โชคและรายได้เสริม', '正财': 'เงินที่ได้จากการลงแรง', '七杀': 'แรงกดดันและความท้าทาย', '正官': 'ผู้ใหญ่ กฎระเบียบ และตำแหน่งงาน', '偏印': 'ความคิดลึก สัญชาตญาณ และการเรียนรู้', '正印': 'ผู้อุปถัมภ์ ความรู้ และเอกสาร' };
    const CONNH = ['ที่เป็นเช่นนี้เพราะ', 'เหตุผลก็เพราะ', 'ที่เป็นแบบนี้ก็เพราะ'];
    const ELH = (el, full) => full ? [`ยามนี้${el}ขึ้นเต็มทั้งยาม`, `ยามนี้มีแต่ธาตุ${el}ทั้งบนและล่าง`, `ยามนี้ธาตุ${el}คุมทั้งยาม`] : [`พลังหลักของยามนี้เป็นธาตุ${el}`, `ยามนี้ธาตุ${el}มีกำลังมากที่สุด`, `ธาตุที่เด่นในยามนี้เป็นธาตุ${el}`];
    const MCONN = (el) => [`ซึ่ง${el}ในดวงคุณคือ`, `และธาตุ${el}ในดวงของคุณหมายถึง`, `ซึ่งในดวงคุณ ธาตุ${el}หมายถึง`];
    const WHY_CLASH = (n) => [`${n}เป็นคู่ตรงข้ามกับตำแหน่งคู่ครองในดวงคุณพอดี ยามนี้จึงเป็นยามที่อารมณ์กับคนใกล้ตัวไหวง่ายที่สุดของวัน`,
        `${n}ไปชนกับตำแหน่งคู่ครองในดวงคุณ ใจจึงร้อนกับคนในบ้านได้ง่าย`, `${n}อยู่ตรงข้ามกับตำแหน่งคู่ครองในดวงคุณ ความสัมพันธ์ใกล้ตัวจึงถูกเขย่าในยามนี้`];
    // ยามดี: ใช้ยามนี้ให้คุ้ม · ยามร้าย: ถ้าจำเป็นต้องทำ
